<template>
  <div class="tabs">
    <nav class="tabs_header">
      <div class="logo" id="logo">
        <img src="@/assets/fastlogo.png" alt="lscc" />
      </div>
      <a
        class="tab_header"
        v-for="tab in tabTitles"
        :key="tab.title"
        :class="{ selected: tab.title === selectedTitle }"
        @click="clickHandle(tab.title)"
      >
        <div class="inner">
          <div class="icon">
            <i :class="['bx', tab.icon]"></i>
          </div>
          {{ tab.title }}
        </div>
      </a>
      <a class="staff" v-if="admin > 0">
        <div class="inner" @click="$emit('toggleStaff')">
          <div class="icon"><i v-if="staff === true" class="bx bx-home-alt"></i><i v-else class="bx bx-lock-open-alt"></i></div>
          <template v-if="staff === true">Back</template><template v-else>Staff</template>
        </div>
      </a>
    </nav>
    <div class="tab-content">
      <transition name="slide" appear>
        <div v-if="tabTitles.find(({ title }) => title === selectedTitle).top" class="top"></div>
      </transition>
      <div class="bottom">
        <slot />
      </div>
    </div>
  </div>
</template>

<script>
import { ref, provide } from "vue";

export default {
  name: "TabsWrapper",
  props: ["staff", "admin"],
  emits: ["toggleStaff"],
  methods: {
    clickHandle(title) {
      this.selectedTitle = title;
    },
    egg() {
      let element = document.getElementById("logo");

      element.classList.remove("eggAnim"); // reset animation
      void element.offsetWidth; // trigger reflow
      element.classList.add("eggAnim"); // start animation
    },
  },
  data() {
    return {
      logoURL: `https://cdn.discordapp.com/attachments/890530526509797376/894658481221664848/RNC_COVER_CONCEPT_2.png`,
    };
  },
  setup(props, { slots }) {
    const tabTitles = ref(slots.default().map((tab) => tab.props));
    const selectedTitle = ref(tabTitles.value[0].title);

    provide("selectedTitle", selectedTitle);
    provide("tabTitles", tabTitles);
    return {
      selectedTitle,
      tabTitles,
    };
  },
};
</script>

<style scoped lang="scss">
.staff {
  position: absolute;
  display: grid;
  justify-content: center;
  align-items: center;
  z-index: 999;
  margin-bottom: 10px;
  bottom: 0;
  min-width: 100%;

  .inner {
    cursor: pointer;
    transition: all 0.4s;
    display: flex;
    justify-content: flex-start;
    align-items: center;
    padding: 10px 23px;
    border-radius: 15px;
    font-size: 17px;
    width: 150px;

    color: #ced6e2a6;
    background: #ced6e221;

    &:hover {
      background: #ced6e244;
    }

    .icon {
      display: grid;
      justify-content: center;
      align-items: center;
      text-align: center;
      width: 42px;

      .bx {
        font-size: 30px;
      }
    }
  }
}

.slide-enter-active {
  animation: slide 0.5s ease-out both;
}

.slide-leave-active {
  animation: slide 0.5s reverse ease-in both;
}

@keyframes slide {
  0% {
    min-height: 0px;
  }
  100% {
    min-height: 60px;
  }
}

.top {
  min-height: 60px;
  display: flex;
  align-items: center;
  font-size: 22px;
  color: #fff;
  //border-bottom: 1px solid $sago-gray2;
  background: $foreground;
  //box-shadow: rgba(0, 0, 0, 0.35) 0px 5px 15px;
}

.bottom {
  background: $background;
  border-radius: 15px;
  flex: 1;
  padding: 10px;
  box-shadow: rgba(0, 0, 0, 0.35) 0px 5px 15px inset;
  overflow: visible !important;
  position: relative;
}

.tab-content {
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
}

.animation {
  position: absolute;
  height: 70px;
  width: 100%;
  /* height: 5px; */
  top: 0;
  /* bottom: 0; */
  z-index: 1;
  background: rgba($background, 0.5);
  border-top-left-radius: 10px;
  border-bottom-left-radius: 10px;
  transition: all 0.5s ease 0s;
}

.tabs {
  font-family: "Nunito", sans-serif;
  font-weight: bold;
  display: flex;
  height: 100%;
  width: 100%;
}

.bx {
  display: flex;
  justify-content: center;
  align-items: center;
  font-size: 27px;
}

.logo {
  width: 100%;
  display: flex;
  justify-content: center;
  align-items: center;
  position: relative;
  //margin: 13px 0px 20px 20px;

  margin: 20px 0px 20px 0px;

  //background: #2d6ae3;

  img {
    width: 150px;
    -webkit-user-drag: none;
  }
}

.tabs_header {
  overflow: visible !important;
  height: 100%;
  width: 200px;
  color: $gray-text;
  position: relative;
  //border-right: 1px solid $sago-gray2;
  font-size: 15px;
  background: $foreground;
  //box-shadow: rgba(0, 0, 0, 0.35) 0px 5px 15px;

  .selected {
    .inner {
      color: $blue !important;
      background: rgba($blue, 0.1);
    }
  }

  .tab_header {
    display: grid;
    justify-content: center;
    align-items: center;
    cursor: pointer;
    z-index: 999;
    position: relative;
    margin-bottom: 5px;

    .inner {
      transition: all 0.4s;
      display: flex;
      justify-content: flex-start;
      align-items: center;
      padding: 10px;
      border-radius: 15px;
      font-size: 17px;
      width: 150px;

      color: #ced6e2a6;

      .icon {
        display: grid;
        justify-content: center;
        align-items: center;
        text-align: center;
        width: 42px;

        .bx {
          font-size: 30px;
        }
      }
    }
  }
}
</style>
