<template>
  <div class="w-full ">
    <div class="flex flex-wrap gap-2 justify-center">
      <CustomSelect @changeType="changeType" :placeholder="'Select type'" :options="options" />
      <input v-model="query" placeholder="Player" class="query" type="text" />
    </div>
    <div class="flex w-full justify-center p-2">
      <button @click="search" class="font-bold text-lg search flex" :disabled="isLoading === true">
        <i v-if="isLoading === true" class="bx bx-loader-alt fa-spin text-lg mr-0.5"></i><i v-else class="bx bx-search text-lg mr-0.5"></i> Search
      </button>
    </div>
    <div class="flex w-full justify-center p-2 overflow-y-auto" style="max-height: 650px; border-radius: 15px">
      <table id="logs">
        <thead>
          <tr>
            <th v-for="row in rows" :key="row">{{ row }}</th>
          </tr>
        </thead>
        <tbody>
          <tr v-for="col in columns" :key="col">
            <td v-for="subCol in col" :key="subCol">{{ subCol }}</td>
          </tr>
        </tbody>
      </table>
    </div>
  </div>
</template>

<script>
import CustomSelect from "../../components/CustomSelect.vue";
import $ from "jquery";

export default {
  name: "LogsTab",
  components: { CustomSelect },
  data() {
    return {
      type: "",
      query: "",
      options: [
        { name: "Sessions", value: "sessions" },
        { name: "Admin", value: "admin" },
        { name: "Records", value: "records" },
      ],
      rows: ["Reason", "Duration", "Timestamp"],
      columns: [
        ["cheating", "30 minutes.", "2021-09-11 23:28:25"],
        ["(#1) Insulting", "10 minutes.", "2021-09-12 12:10:39"],
        ["(#1) Being toxic + Insulting people", "N/A", "2021-09-12 13:24:42"],
        ["Hacks + Aimbot", "999999999 minutes.", "2021-09-12 15:25:43"],
        ["(#1) Ramming", "1 minute.", "2021-09-12 15:25:47"],
        ["(#2) VDM", "N/A", "2021-09-12 19:11:28"],
        ["cheating", "30 minutes.", "2021-09-11 23:28:25"],
        ["(#1) Insulting", "10 minutes.", "2021-09-12 12:10:39"],
        ["(#1) Being toxic + Insulting people", "N/A", "2021-09-12 13:24:42"],
        ["Hacks + Aimbot", "999999999 minutes.", "2021-09-12 15:25:43"],
        ["(#1) Ramming", "1 minute.", "2021-09-12 15:25:47"],
        ["(#2) VDM", "N/A", "2021-09-12 19:11:28"],
        ["(#1) Being toxic + Insulting people", "N/A", "2021-09-12 13:24:42"],
        ["Hacks + Aimbot", "999999999 minutes.", "2021-09-12 15:25:43"],
        ["(#1) Ramming", "1 minute.", "2021-09-12 15:25:47"],
        ["(#2) VDM", "N/A", "2021-09-12 19:11:28"],
        ["(#1) Being toxic + Insulting people", "N/A", "2021-09-12 13:24:42"],
        ["Hacks + Aimbot", "999999999 minutes.", "2021-09-12 15:25:43"],
        ["(#1) Ramming", "1 minute.", "2021-09-12 15:25:47"],
        ["(#2) VDM", "N/A", "2021-09-12 19:11:28"],
      ],
      isLoading: false,
      cooldown: 1500,
    };
  },
  mounted() {
    this.type = this.options[0].value;

    // Change the selector if needed
    var $table = $("table.scroll"),
      $bodyCells = $table.find("tbody tr:first").children(),
      colWidth;

    // Adjust the width of thead cells when window resizes
    $(window)
      .resize(function() {
        // Get the tbody columns width array
        colWidth = $bodyCells
          .map(function() {
            return $(this).width();
          })
          .get();

        // Set the width of thead columns
        $table
          .find("thead tr")
          .children()
          .each(function(i, v) {
            $(v).width(colWidth[i]);
          });
      })
      .resize(); // Trigger resize handler
  },
  methods: {
    changeType(type) {
      console.log("type", type);
      this.type = type;
    },
    search() {
      // eslint-disable-next-line no-undef
      mp.trigger("RequestLogsFromServer", this.type, this.query);
      this.isLoading = true;
      setTimeout(() => {
        this.isLoading = false;
      }, this.cooldown);
    },
  },
};
</script>

<style lang="scss" scoped>
::-webkit-scrollbar {
  width: 0px;
}

.query {
  color: lighten($gray, 30%);
  background: darken($gray, 10%);
  border-radius: 5px;
  font-weight: bold;
  font-size: 18px;
  padding: 10px 20px;
  width: 200px;
  border: 2px solid $gray;

  &::placeholder {
    color: lighten($gray, 30%);
  }

  &:focus {
    outline: none;
  }
}

.search {
  color: #ced6e2a6;
  background: #ced6e221;
  padding: 10px 23px;
  border-radius: 15px;
  font-weight: bold;
  transition: all 0.4s;

  &[disabled] {
    pointer-events: none;
    background: #ced6e244;
  }

  &:hover {
    background: #ced6e244;
  }
}

#logs {
  font-family: Arial, Helvetica, sans-serif;
  border-collapse: separate;
  border: solid $gray 2px;
  border-radius: 6px;
  width: 100%;
  color: lighten($gray, 30%);
  border-radius: 6px;
  border-spacing: 0;
  background: $gray;

  tbody td:last-child,
  thead th:last-child {
    border-right: none;
  }

  & th:first-child {
    border-radius: 6px 0 0 6px;
  }

  & th:last-child {
    border-radius: 0 6px 6px 0;
  }
}

#logs td,
#logs th {
  //border: 1px solid $gray;
  padding: 8px;
}

#logs tr {
  background: $gray;
}

#logs tr:nth-child(even) {
  background-color: darken($gray, 2.5%);
}

#logs tr:hover {
  background-color: lighten($gray, 5%);
}

#logs th {
  padding-top: 12px;
  padding-bottom: 12px;
  text-align: left;
  background-color: rgb(65, 82, 116);
  color: $blue;
}
</style>
