<template>
  <div class="tabs">
    <ul class="tabs_header">
      <li
        class="tab_header"
        v-for="tab in tabTitles"
        :key="tab.title"
        :class="{ selectedFugi: selectedTitle === 'Fugitive' && tab.title === selectedTitle, selected: tab.title === selectedTitle }"
        @click="selectedTitle = tab.title"
      >
        {{ tab.title }}
      </li>
    </ul>
    <slot />
  </div>
</template>

<script>
import { ref, provide } from "vue";

export default {
  name: "LoadoutsTabsWrapper",
  setup(props, { slots }) {
    const tabTitles = ref(slots.default().map((tab) => tab.props));
    const selectedTitle = ref(tabTitles.value[0].title);

    provide("selectedTitle", selectedTitle);
    return {
      selectedTitle,
      tabTitles,
    };
  },
};
</script>

<style scoped lang="scss">
.tabs {
  display: flex;
  flex-direction: column;
  height: 100%;
  width: 100%;
  position: relative;
}

.tabs_header {
  display: flex;
  width: 100%;
  justify-content: center;
  align-items: center;
  color: #ced6e2a6;
  //border-bottom: 1px solid $sago-gray2;
  font-weight: bold;

  position: absolute;
  top: -61px;
  z-index: 150;

  .selected {
    color: $blue !important;
    background: rgba($blue, 0.1);
  }

  .selectedFugi {
    color: $orange !important;
    background: rgba($orange, 0.1);
  }

  .tab_header {
    margin: 0px 10px 0 10px;
    display: grid;
    justify-content: center;
    align-items: center;
    cursor: pointer;
    padding: 10px;
    border-radius: 15px;
    font-size: 17px;
  }
}
</style>
